  {
    title: 'Senior Full-stack Engineer',
    company: 'QuantumGPT',
    dates: 'Mar 2024 - Present',
    desc: 'Architecting scalable full-stack solutions for enterprise AI platforms.',
    achievements: [
      'Scaled a 40GB real-time analytics dashboard by 30%.',
      'Optimized GraphQL resolvers to reduce cold-start latency by 45%.',
    ],
  },
  {
    title: 'AI Researcher',
    company: 'NeuralNetX',
    dates: 'Oct 2022 - Feb 2024',
    desc: 'Developed advanced NLP models for enterprise chatbots and content generation.',
    achievements: [
      'Published 4 research papers in top-tier AI conferences.',
      'Led a 12-person ML team achieving a 20% performance boost.',
