];

export default function About() {
  const [isHovered, setIsHovered] = useState(false);
  const [isSparkleActive, setIsSparkleActive] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const [formData, setFormData] = useState({
    name: 'Amey Chikane',
    email: 'amey@quantumgpt.com',
    message: '',
  });

  const [skills, setSkills] = useState(INITIAL_SKILLS);
  const [experience, setExperience] = useState(INITIAL_EXPERIENCE);

  const handleSparkleToggle = () => {
    setIsSparkleActive(!isSparkleActive);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setIsLoading(true);

    setTimeout(() => {
      setIsLoading(false);
      setIsSparkleActive(true);
      setTimeout(() => {
        setIsSparkleActive(false);
      }, 1500);
    }, 1200);
  };

