          <div className="relative mb-16 sm:mb-24">
            <div className="absolute top-0 left-0 right-0 h-4 bg-gradient-to-r from-indigo-600 via-purple-600 to-pink-600" />
            <div className="relative z-10">
              <h2 className="text-3xl sm:text-4xl font-bold text-center text-slate-100 tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 via-purple-400 to-pink-400">About Me</h2>
              <p className="text-sm sm:text-base mt-4 max-w-lg mx-auto text-slate-400 text-center">Engineered solutions that make sense in the digital age.</p>
            </div>
          </div>

          {/* Main Card Grid */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 sm:gap-8 justify-items-center">
            {/* Personal Info Card */}
            <div className="group relative overflow-hidden rounded-2xl bg-white/5 p-6 backdrop-blur-xl border border-white/10 hover:border-white/20 transition-all duration-300 shadow-2xl shadow-indigo-900/30">
              <div className="absolute -top-12 -right-12 w-36 h-36 bg-gradient-to-br from-indigo-600/20 to-purple-600/20 rounded-full blur-3xl pointer-events-none" />
              <div className="relative z-10 flex items-center gap-4">
                <div className="w-16 h-16 rounded-2xl bg-white/10 border border-white/20 flex items-center justify-center text-slate-400 shadow-inner transition-all duration-300 group-hover:border-white group-hover:text-slate-200">
                  <User className="w-6 h-6 text-indigo-400" />
                </div>
                <div>
                  <h3 className="text-lg font-semibold text-slate-100">{formData.name}</h3>
                  <p className="text-sm text-slate-400">Full-stack Engineer | AI & DevOps Specialist</p>
                </div>
              </div>
              <div className="mt-8 space-y-4">
                <div className="flex items-center gap-2 text-slate-400">
                  <MapPin className="w-4 h-4 text-slate-500" /> <span>Bangalore, India</span>
                </div>
                <div className="flex items-center gap-2 text-slate-400">
                  <Github className="w-4 h-4 text-slate-500" /> <a href="https://github.com/ameyc" target="_blank" rel="noreferrer" className="text-indigo-400 hover:underline">@ameyc</a>
                </div>
              </div>
            </div>

            {/* Skill Pill Cards */}
            <div className="w-full max-w-md mx-auto">
              <div className="space-y-4 py-6 sm:py-8">
                {skills.map((skill, i) => (
                  <div key={i} className="flex items-center gap-2 px-3 py-2 rounded-xl bg-white/5 border border-white/10 text-sm font-medium text-slate-400 transition-colors duration-300 hover:bg-white/10">
                    <div className="flex items-center gap-1">
                      <skill.icon {...{ size: 12, className: "text-slate-500" }} />
                      {skill.name}
                    </div>
                    <span className="flex-1" />
                    <span className="text-xs text-slate-500">{skill.value}</span>
                  </div>
                ))}
              </div>
            </div>

            {/* Experience Stats Card */}
            <div className="group relative overflow-hidden rounded-2xl bg-white/5 p-6 backdrop-blur-xl border border-white/10 hover:border-white/20 transition-all duration-300 shadow-2xl shadow-indigo-900/30">
              <div className="absolute -top-12 -right-12 w-36 h-36 bg-gradient-to-br from-indigo-600/20 to-purple-600/20 rounded-full blur-3xl pointer-events-none" />
              <div className="relative z-10 flex flex-col items-start justify-between min-h-[150px]">
                <div className="flex items-center justify-between w-full">
                  <div>
                    <h4 className="text-sm font-semibold text-slate-100">Experience</h4>
                    <p className="text-xs text-slate-400">Enterprise-grade solutions & scale</p>
                  </div>
                  <Bell className="w-5 h-5 text-slate-500 group-hover:text-indigo-400" onClick={handleSparkleToggle} />
                </div>
                <div className="flex items-center gap-4">
                  {experience.map((exp, i) => (
                    <div key={i} className="flex flex-col gap-1 text-slate-400">
                      <span className="text-xs font-semibold tracking-wide">{exp.title}</span>
                      <span className="text-xs text-slate-500">{exp.company}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {/* Gradient CTA Button */}
          <div className="relative py-12 sm:py-16">
            <div className="absolute inset-0 bg-gradient-to-br from-indigo-600/10 to-purple-600/10" />
            <div className="relative z-10">
              <button
                onClick={handleSubmit}
                className="w-full max-w-md mx-auto bg-indigo-600 hover:bg-indigo-500 text-white font-semibold py-3 rounded-2xl border border-indigo-700 shadow-lg shadow-indigo-500/30 hover:scale-[1.02] transition-transform duration-200 active:scale-[0.98]"
              >
                {isLoading ? 'Sending...' : 'Send Message'}
                {isSparkleActive && <Sparkle className="w-4 h-4 text-indigo-400 animate-pulse" />}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default function Faq() {
  return (
    <section id="faq" className="py-20">
      <div className="max-w-4xl mx-auto px-6 text-slate-700">
        <h2 className="text-3xl font-bold mb-4">Faq</h2>
      </div>
    </section>
  );
}

