export default function Testimonials() {
  const [activeTab, setActiveTab] = useState('all');
  const [isLoading, setIsLoading] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [formData, setFormData] = useState({ name: '', email: '', company: '', message: '' });

  const handleSubmit = (e) => {
    e.preventDefault();
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      setModalOpen(false);
    }, 1200);
  };

  return (
    <section id="reviews" className="w-full min-h-screen bg-slate-900 text-slate-100 font-sans">
      <div className="max-w-7xl mx-auto px-6 py-20 relative z-10">
        {/* Top Decorative Decorations */}
        <div className="absolute -top-24 left-1/2 -translate-x-1/2 w-96 h-96 bg-purple-600/20 rounded-full blur-3xl pointer-events-none" />
        <div className="absolute -top-20 left-1/4 -translate-x-1/2 w-48 h-48 bg-indigo-600/20 rounded-full blur-3xl pointer-events-none" />
        <div className="absolute -top-24 right-1/2 -translate-x-1/2 w-96 h-96 bg-pink-600/20 rounded-full blur-3xl pointer-events-none" />

        {/* Hero Section */}
        <div className="max-w-md mx-auto text-center">
          <h2 className="text-3xl sm:text-4xl font-bold tracking-tight text-slate-100 bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-purple-500 mb-6">
            Client Feedback & Testimonials
          </h2>
          <p className="text-slate-400 text-sm sm:text-base mb-12">
            Real opinions from satisfied clients about their experiences with The Business.
          </p>
        </div>

        {/* Filter Tabs */}
        <div className="mx-auto max-w-md sm:max-w-2xl">
          <div className="flex justify-center mb-12">
            {['all', 'positive', 'neutral', 'negative'].map((type) => (
              <button
                key={type}
                onClick={() => setActiveTab(type)}
                className="inline-flex items-center gap-2 px-3 py-2 rounded-xl text-sm font-medium transition-colors duration-200 bg-white/5 border border-white/10 hover:bg-white/10 active:scale-95"
                style={{ backgroundColor: type === 'positive' ? 'var(--tw-gradient-to-r, from-indigo-600/20 via-purple-600/20 to-rose-600/20)' : type === 'neutral' ? 'var(--tw-gradient-to-r, from-slate-700/10 via-cyan-600/10 to-white/0)' : 'white/20' }}
              >
                <div className="w-2.5 h-2.5 rounded-full bg-white/30" />
                {type.toUpperCase()}
              </button>
            ))}
          </div>
        </div>

        {/* Testimonial Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 mb-16">
          {testimonials.filter((test) => (activeTab === 'all' || test.review.includes(activeTab)) && !isLoading).map((test) => (
            <div key={test.id} className="group relative rounded-2xl bg-white/5 backdrop-blur-xl border border-white/10 p-6 transition-all duration-300 hover:shadow-2xl hover:scale-[1.02]">
              <div className="absolute -top-1 -right-1 w-5 h-5 rounded-full bg-white/10 border border-white/20 group-hover:bg-white/20" />
              <div className="absolute -bottom-1 -right-1 w-5 h-5 rounded-full bg-white/10 border border-white/20 group-hover:bg-white/20" />
              <div className="absolute -top-1 -left-1 w-5 h-5 rounded-full bg-white/10 border border-white/20 group-hover:bg-white/20" />
              <div className="absolute -bottom-1 -left-1 w-5 h-5 rounded-full bg-white/10 border border-white/20 group-hover:bg-white/20" />

              <div className="flex items-start justify-between mb-8">
                <div className="flex items-start space-x-3">
                  <div className="p-3 rounded-xl bg-indigo-600/10 text-indigo-400 shadow-lg shadow-indigo-500/20">
                    <Star className="w-5 h-5" />
                  </div>
                  <div>
                    <p className="text-slate-400 text-sm">{test.review}</p>
                    <h3 className="font-bold text-slate-100 text-sm">{test.name}</h3>
                    <p className="text-slate-400 text-xs mt-1">{test.title}</p>
                    <p className="text-slate-400 text-xs mt-1">{test.company}</p>
                  </div>
                </div>
                <div className="flex items-center space-x-2">
                  <User className="w-5 h-5 text-slate-400" />
                  <MapPin className="w-5 h-5 text-slate-400" />
                </div>
              </div>

              {/* Decorative Gradient Border */}
              <div className="absolute inset-0 pointer-events-none bg-gradient-to-br from-white/5 via-white/10 to-white/0" />

              {/* Bottom Decorative Glow */}
              <div className="absolute -bottom-24 left-1/2 -translate-x-1/2 w-96 h-96 bg-white/5 rounded-full blur-3xl pointer-events-none" />
            </div>
          ))}
        </div>

        {/* Add Review Modal */}
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md transition-all duration-300">
          {modalOpen ? (
            <div className="relative w-full max-w-sm overflow-hidden rounded-2xl bg-white/10 backdrop-blur-xl border border-white/10/30 p-6 shadow-2xl transition-all duration-300 transform hover:scale-102">
              <div className="absolute top-4 right-4 p-2 rounded-xl bg-white/20 border border-white/10 hover:bg-white/30">
                <button onClick={() => setModalOpen(false)} className="text-slate-400 hover:text-white">
                  <X className="w-4 h-4" />
                </button>
              </div>

              <div className="text-center mb-8">
                <h3 className="text-xl font-bold text-slate-100 mb-2">Share Your Feedback</h3>
                <p className="text-slate-400 text-sm">Help us improve The Business with your valuable insights.</p>
              </div>

              <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="relative">
                    <User className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
                    <input 
                      type="text" 
                      placeholder="Your Name (Optional)" 
                      className="w-full bg-white/5 border border-white/10 text-slate-300 placeholder:text-slate-500 text-sm rounded-xl py-3 pl-11 pr-4 transition-all duration-200 focus:ring-2 focus:ring-indigo-500/30 outline-none"
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    />
                  </div>
                  <div className="relative">
                    <Mail className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
                    <input 
                      type="email" 
                      placeholder="Email Address" 
                      className="w-full bg-white/5 border border-white/10 text-slate-300 placeholder:text-slate-500 text-sm rounded-xl py-3 pl-11 pr-4 transition-all duration-200 focus:ring-2 focus:ring-indigo-500/30 outline-none"
                      value={formData.email}
                      onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                    />
                  </div>
                </div>

                <div className="relative">
                  <Users className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
                  <input 
                    type="text" 
                    placeholder="Company (Optional)" 
                    className="w-full bg-white/5 border border-white/10 text-slate-300 placeholder:text-slate-500 text-sm rounded-xl py-3 pl-11 pr-4 transition-all duration-200 focus:ring-2 focus:ring-indigo-500/30 outline-none"
                    value={formData.company}
                    onChange={(e) => setFormData({ ...formData, company: e.target.value })}
                  />
                </div>

                <textarea 
                  placeholder="Your Review or Feedback" 
                  className="w-full bg-white/5 border border-white/10 text-slate-300 placeholder:text-slate-500 text-sm rounded-xl py-3 px-4 resize-none transition-all duration-200 focus:ring-2 focus:ring-indigo-500/30 outline-none"
                  rows="6"
                  value={formData.message}
                  onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                ></textarea>

                <button 
                  type="submit"
                  disabled={isLoading}
                  className="w-full bg-indigo-600 hover:bg-indigo-500 text-white py-3 rounded-xl font-semibold transition-all duration-200 hover:scale-102"
                >
                  {isLoading ? <span className="inline-flex items-center gap-1"><Sparkles className="w-4 h-4 animate-spin text-white" /> Submitting...</span> : "Submit Review"}
                </button>
              </form>
            </div>
          ) : (
            <button 
              onClick={() => setModalOpen(true)}
              className="fixed bottom-10 right-10 bg-white/10 text-slate-400 hover:text-white border border-white/20 rounded-xl p-4 shadow-lg transition-all duration-200 hover:bg-white/20"
            >
              <Plus className="w-6 h-6" />
            </button>
          )}
        </div>
      </div>
    </section>
  );
}
